// FUNCTIONS //

/**
* Creates a Vega specification from a figure configuration.
*
* @private
* @param {Object} config - figure configuration
* @param {Object} config.title - Vega title object
* @param {number} [config.width] - override width
* @param {number} [config.height] - override height
* @param {number} [config.padding] - override padding
* @param {string} [config.background] - background color
* @param {Array} [config.scales] - Vega scale definitions
* @param {Array} [config.axes] - Vega axis definitions
* @param {Array} [config.marks] - Vega mark definitions
* @returns {Object} Vega specification
*/
function createSpec( config ) {
	var spec;

	spec = {
		'$schema': SCHEMA,
		'width': config.width || BASE_WIDTH,
		'height': config.height || BASE_HEIGHT,
		'padding': config.padding || BASE_PADDING,
		'title': config.title,
		'background': config.background || '#ffffff',
		'marks': config.marks || GROUP_RECT_MARKS,
		'scales': config.scales || [],
		'axes': config.axes || []
	};
	return spec;
}

/**
* Generates all figure SVGs sequentially.
*
* @private
* @param {Array} figures - figure configuration array
* @param {Callback} clbk - callback to invoke upon completion
* @returns {void}
*/
function generateAll( figures, clbk ) {
	var idx = 0;
	next();

	/**
	* Processes the next figure in the queue.
	*
	* @private
	* @returns {void}
	*/
	function next() {
		var outputPath;
		var config;
		var spec;

		if ( idx >= figures.length ) {
			return clbk( null );
		}
		config = figures[ idx ];
		spec = createSpec( config );
		outputPath = join( IMG_DIR, config.name + '.svg' );

		debug( 'Rendering: %s', config.name );
		renderFig( outputPath, spec, onDone );
	}

	/**
	* Callback invoked upon completing a figure render.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @returns {void}
	*/
	function onDone( error ) {
		if ( error ) {
			return clbk( error );
		}
		debug( '  -> %s', join( IMG_DIR, figures[ idx ].name + '.svg' ) );
		idx += 1;
		next();
	}
}

/**
* Removes stale SVG files from a directory listing.
*
* @private
* @param {Array} files - directory entries
* @throws {Error} if unable to remove a stale file
* @returns {void}
*/
function removeStaleFiles( files ) {
	var valid;
	var file;
	var err;
	var f;
	var i;
	var j;

	for ( i = 0; i < files.length; i++ ) {
		file = files[ i ];
		if ( extname( file ) !== '.svg' ) {
			continue;
		}
		valid = false;
		for ( j = 0; j < FIGURES.length; j++ ) {
			f = FIGURES[ j ].name + '.svg';
			if ( file === f ) {
				valid = true;
				break;
			}
		}
		if ( !valid ) {
			debug( 'Removing stale SVG: %s', file );
			err = unlinkSync( join( IMG_DIR, file ) );
			if ( err instanceof Error ) {
				throw err;
			}
		}
	}
}


// MAIN //

/**
* Generates all title documentation figures.
*
* @private
* @returns {void}
*/
function main() {
	var files;

	if ( existsSync( IMG_DIR ) ) {
		files = readdirSync( IMG_DIR );
		if ( files instanceof Error ) {
			console.error( 'Error reading directory: %s', files.message ); // eslint-disable-line no-console
			process.exitCode = 1;
			return;
		}
		removeStaleFiles( files );
	}
	// Generate all figure SVGs:
	generateAll( FIGURES, onComplete );

	/**
	* Callback invoked upon completing all figure generation.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @returns {void}
	*/
	function onComplete( error ) {
		if ( error ) {
			console.error( 'Error generating figures: %s', error.message ); // eslint-disable-line no-console
			process.exitCode = 1;
			return;
		}
		console.log( 'Successfully generated %d title figures.', FIGURES.length ); // eslint-disable-line no-console
	}
}

main();
